def gen(rng):
    def digs(n):
        if n == 1:
            return [rng.randint(0, 9)]
        return [rng.randint(1, 9)] + [rng.randint(0, 9) for _ in range(n - 1)]

    def fmt(a, b):
        return str(len(a)) + '\n' + ' '.join(map(str, a)) + '\n' + str(len(b)) + '\n' + ' '.join(map(str, b))

    tests = [fmt([0], [0]), fmt([0], [5]), fmt([9], [1]), fmt([9] * 5, [1]), fmt([1, 0, 0, 0, 0], [9, 9, 9, 9]),
             fmt([1, 2, 3], [4, 5, 6]), fmt([5], [9, 9, 5]), fmt([4, 9, 9], [5, 0, 1])]
    for _ in range(14):
        tests.append(fmt(digs(rng.randint(1, 12)), digs(rng.randint(1, 12))))
    for _ in range(4):
        k = rng.randint(1, 12)
        tests.append(fmt(digs(k), digs(k)))
    tests.append(fmt(digs(2000), digs(1500)))
    N = 100000
    tests.append(fmt(digs(N), digs(N)))
    tests.append(fmt([9] * N, [1]))
    tests.append(fmt(digs(N), digs(N // 2)))
    tests.append(fmt([9] * N, [9] * N))
    return tests

